-- 세트 236: 설정 주입 실습: ConfigMap·Secret 만들기, 환경변수와 볼륨으로 주입, 설정 오류 진단, 값 바꾸고 반영하기
-- 명세: docs/specs/spec_k8s_config_inject_set.md. 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (236, 1, '--from-literal 로 ConfigMap 만들기', '`app-cfg` 라는 ConfigMap 을 만드세요. 키 `GREETING` 의 값은 `hello-etude`, 키 `LEVEL` 의 값은 `info` 입니다. 만든 뒤 `describe` 로 내용을 확인해 보세요.', '`kubectl create configmap 이름 --from-literal=키=값` 을 키마다 한 번씩 쓸 수 있어요. 확인은 `kubectl describe configmap 이름` 입니다.', 'kubectl create configmap app-cfg --from-literal=GREETING=hello-etude --from-literal=LEVEL=info -n $NS
kubectl describe configmap app-cfg -n $NS

# ConfigMap 은 키와 값을 모아 두는 오브젝트다. Pod 와 따로 만들어 두고 나중에 연결한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/app.properties; kubectl delete pod envdemo volpod broken -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete deployment api -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete configmap app-cfg file-cfg pay-cfg -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete secret db-secret -n $NS --ignore-not-found >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get configmap app-cfg -n $NS -o jsonpath=''{.data.GREETING}'' 2>/dev/null)\\" = \\"hello-etude\\" ] ) && ( [ \\"$(kubectl get configmap app-cfg -n $NS -o jsonpath=''{.data.LEVEL}'' 2>/dev/null)\\" = \\"info\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "GREETING 이 hello-etude 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get configmap app-cfg -n $NS -o jsonpath=''{.data.GREETING}'' 2>/dev/null)\\" = \\"hello-etude\\" ]"]}, {"label": "LEVEL 이 info 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get configmap app-cfg -n $NS -o jsonpath=''{.data.LEVEL}'' 2>/dev/null)\\" = \\"info\\" ]"]}]', '[{"title": "ConfigMap", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}, {"title": "Secret", "url": "https://kubernetes.io/docs/concepts/configuration/secret/"}, {"title": "컨테이너 환경 변수 정의", "url": "https://kubernetes.io/docs/tasks/inject-data-application/define-environment-variable-container/"}]'),
  (236, 2, '--from-file 로 파일째 ConfigMap 만들기', '먼저 `/tmp/app.properties` 파일을 만들고 안에 두 줄 `mode=prod`, `port=8080` 을 쓰세요. 그다음 이 **파일을 통째로** 담은 ConfigMap `file-cfg` 를 만드세요.', '`kubectl create configmap 이름 --from-file=경로` 를 쓰면 파일 이름이 키가 되고 파일 내용이 값이 돼요. 파일은 `printf` 나 `cat > 파일 <<EOF` 로 만들 수 있어요.', 'printf ''mode=prod\\nport=8080\\n'' > /tmp/app.properties
kubectl create configmap file-cfg --from-file=/tmp/app.properties -n $NS
kubectl describe configmap file-cfg -n $NS

# 키는 파일 이름(app.properties), 값은 파일 내용 전체이다
# 설정 파일을 그대로 Pod 안에 놓고 싶을 때 쓴다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/app.properties; kubectl delete pod envdemo volpod broken -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete deployment api -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete configmap app-cfg file-cfg pay-cfg -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete secret db-secret -n $NS --ignore-not-found >/dev/null 2>&1; true"]', '["sh", "-c", "( kubectl get configmap file-cfg -n $NS -o jsonpath=''{.data.app\\\\.properties}'' 2>/dev/null | grep -q \\"^mode=prod$\\" ) && ( kubectl get configmap file-cfg -n $NS -o jsonpath=''{.data.app\\\\.properties}'' 2>/dev/null | grep -q \\"^port=8080$\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "키 app.properties 가 있고 mode=prod 가 들어 있다", "cmd": ["sh", "-c", "kubectl get configmap file-cfg -n $NS -o jsonpath=''{.data.app\\\\.properties}'' 2>/dev/null | grep -q \\"^mode=prod$\\""]}, {"label": "port=8080 도 들어 있다", "cmd": ["sh", "-c", "kubectl get configmap file-cfg -n $NS -o jsonpath=''{.data.app\\\\.properties}'' 2>/dev/null | grep -q \\"^port=8080$\\""]}]', '[{"title": "ConfigMap", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}, {"title": "Secret", "url": "https://kubernetes.io/docs/concepts/configuration/secret/"}, {"title": "컨테이너 환경 변수 정의", "url": "https://kubernetes.io/docs/tasks/inject-data-application/define-environment-variable-container/"}]'),
  (236, 3, 'create secret generic 으로 Secret 만들기', '`db-secret` 이라는 Secret 을 만드세요. 키 `user` 의 값은 `etude`, 키 `password` 의 값은 `change-me-123` 입니다. (연습용 값이에요.)', '`kubectl create secret generic 이름 --from-literal=키=값` 형식입니다. ConfigMap 과 거의 같고 `secret generic` 이 붙어요.', 'kubectl create secret generic db-secret --from-literal=user=etude --from-literal=password=change-me-123 -n $NS
kubectl get secret db-secret -n $NS

# 저장된 값은 base64 로 인코딩되어 있다. 암호화가 아니라 단순 변환이다
# 값을 보려면 kubectl get secret db-secret -o jsonpath=''{.data.password}'' | base64 -d', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/app.properties; kubectl delete pod envdemo volpod broken -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete deployment api -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete configmap app-cfg file-cfg pay-cfg -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete secret db-secret -n $NS --ignore-not-found >/dev/null 2>&1; true"]', '["sh", "-c", "( kubectl get secret db-secret -n $NS >/dev/null 2>&1 ) && ( [ \\"$(kubectl get secret db-secret -n $NS -o jsonpath=''{.data.user}'' 2>/dev/null | base64 -d)\\" = \\"etude\\" ] ) && ( [ \\"$(kubectl get secret db-secret -n $NS -o jsonpath=''{.data.password}'' 2>/dev/null | base64 -d)\\" = \\"change-me-123\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Secret db-secret 이 있다", "cmd": ["sh", "-c", "kubectl get secret db-secret -n $NS >/dev/null 2>&1"]}, {"label": "user 를 풀면 etude 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get secret db-secret -n $NS -o jsonpath=''{.data.user}'' 2>/dev/null | base64 -d)\\" = \\"etude\\" ]"]}, {"label": "password 를 풀면 change-me-123 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get secret db-secret -n $NS -o jsonpath=''{.data.password}'' 2>/dev/null | base64 -d)\\" = \\"change-me-123\\" ]"]}]', '[{"title": "ConfigMap", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}, {"title": "Secret", "url": "https://kubernetes.io/docs/concepts/configuration/secret/"}, {"title": "컨테이너 환경 변수 정의", "url": "https://kubernetes.io/docs/tasks/inject-data-application/define-environment-variable-container/"}]'),
  (236, 4, 'valueFrom 으로 키 하나를 환경변수로', 'ConfigMap `app-cfg` 가 있습니다. Pod `envdemo` 를 YAML 로 만들어 `kubectl apply` 하세요. 이미지 `busybox:1.36`, 명령 `sleep 3600`, 환경변수 `GREETING` 의 값은 **ConfigMap `app-cfg` 의 키 `GREETING`** 에서 가져옵니다. Pod 가 Ready 가 되면 `kubectl exec` 으로 값을 확인하세요.', '`kubectl run envdemo --image=busybox:1.36 --dry-run=client -o yaml -- sleep 3600` 로 뼈대를 얻고, 컨테이너 아래 `env` 에 `valueFrom` → `configMapKeyRef` (name, key) 를 적어요.', 'cat > /tmp/envdemo.yaml <<''EOF''
apiVersion: v1
kind: Pod
metadata:
  name: envdemo
spec:
  containers:
  - name: main
    image: busybox:1.36
    command: ["sleep", "3600"]
    env:
    - name: GREETING
      valueFrom:
        configMapKeyRef:
          name: app-cfg
          key: GREETING
EOF
kubectl apply -n $NS -f /tmp/envdemo.yaml
kubectl wait --for=condition=Ready pod/envdemo -n $NS --timeout=60s
kubectl exec envdemo -n $NS -- printenv GREETING

# 값을 YAML 에 적지 않고 ConfigMap 의 키를 가리킨다
# 같은 ConfigMap 을 여러 Pod 가 함께 쓸 수 있다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/app.properties; kubectl delete pod envdemo volpod broken -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete deployment api -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete configmap app-cfg file-cfg pay-cfg -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete secret db-secret -n $NS --ignore-not-found >/dev/null 2>&1; kubectl create configmap app-cfg --from-literal=GREETING=hello-etude --from-literal=LEVEL=info -n $NS >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get pod envdemo -n $NS -o jsonpath=''{.spec.containers[0].env[?(@.name==\\"GREETING\\")].valueFrom.configMapKeyRef.name}'' 2>/dev/null)\\" = \\"app-cfg\\" ] ) && ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl exec envdemo -n $NS -- printenv GREETING 2>/dev/null)\\" = \\"hello-etude\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "env 가 configMapKeyRef 로 app-cfg 를 가리킨다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod envdemo -n $NS -o jsonpath=''{.spec.containers[0].env[?(@.name==\\"GREETING\\")].valueFrom.configMapKeyRef.name}'' 2>/dev/null)\\" = \\"app-cfg\\" ]"]}, {"label": "Pod 안에서 GREETING 이 hello-etude 이다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl exec envdemo -n $NS -- printenv GREETING 2>/dev/null)\\" = \\"hello-etude\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}]', '[{"title": "ConfigMap", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}, {"title": "Secret", "url": "https://kubernetes.io/docs/concepts/configuration/secret/"}, {"title": "컨테이너 환경 변수 정의", "url": "https://kubernetes.io/docs/tasks/inject-data-application/define-environment-variable-container/"}]'),
  (236, 5, 'Secret 의 키를 가리키는 필드', 'Secret 의 키 하나를 환경변수로 쓸 때는 `valueFrom` 아래에 Secret 을 가리키는 필드를 씁니다. 필드 목록은 `kubectl explain` 으로 볼 수 있어요. 빈칸에 알맞은 필드를 고르세요.', '이름에 "Secret" 과 "KeyRef(키 참조)" 가 들어 있어요. ConfigMap 용은 앞 글자가 달라요.', NULL, NULL, '[]', 'fill', '["secretKeyRef", "configMapKeyRef", "fieldRef", "resourceFieldRef"]', NULL, '`valueFrom` 아래의 `secretKeyRef` 는 Secret 의 이름(name)과 키(key)를 받아 그 값을 환경변수로 넣습니다. `configMapKeyRef` 는 ConfigMap 용, `fieldRef` 는 Pod 자신의 정보(이름, IP 등), `resourceFieldRef` 는 CPU·메모리 요청 같은 리소스 값을 가져옵니다. 사용법은 `configMapKeyRef` 와 같지만 가리키는 오브젝트가 Secret 이라는 점만 달라요.', '[0]', 'kubectl explain pod.spec.containers.env.valueFrom.{0}', NULL, NULL),
  (236, 6, 'ConfigMap 을 볼륨으로 마운트해 파일로 읽기', 'ConfigMap `app-cfg` 가 있습니다. Pod `volpod` 를 YAML 로 만들어 `apply` 하세요. 이미지 `busybox:1.36`, 명령 `sleep 3600`, `app-cfg` 를 볼륨으로 만들어 컨테이너의 **`/etc/app`** 에 마운트합니다. Ready 가 된 뒤 **`GREETING` 파일의 내용**을 `kubectl exec` 로 읽어 `/tmp/mounted.txt` 에 저장하세요.', 'Pod 의 `spec.volumes` 에 `configMap: name: app-cfg` 볼륨을 정의하고, 컨테이너의 `volumeMounts` 에서 `mountPath: /etc/app` 로 연결해요. 마운트하면 키 이름이 파일 이름이 됩니다.', 'cat > /tmp/volpod.yaml <<''EOF''
apiVersion: v1
kind: Pod
metadata:
  name: volpod
spec:
  containers:
  - name: main
    image: busybox:1.36
    command: ["sleep", "3600"]
    volumeMounts:
    - name: cfg
      mountPath: /etc/app
  volumes:
  - name: cfg
    configMap:
      name: app-cfg
EOF
kubectl apply -n $NS -f /tmp/volpod.yaml
kubectl wait --for=condition=Ready pod/volpod -n $NS --timeout=60s
kubectl exec volpod -n $NS -- ls /etc/app
kubectl exec volpod -n $NS -- cat /etc/app/GREETING > /tmp/mounted.txt
cat /tmp/mounted.txt

# ConfigMap 의 키 하나가 파일 하나가 된다 (GREETING, LEVEL)
# 환경변수 대신 설정 파일 형태로 읽는 앱에 맞다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/app.properties; kubectl delete pod envdemo volpod broken -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete deployment api -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete configmap app-cfg file-cfg pay-cfg -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete secret db-secret -n $NS --ignore-not-found >/dev/null 2>&1; kubectl create configmap app-cfg --from-literal=GREETING=hello-etude --from-literal=LEVEL=info -n $NS >/dev/null 2>&1; true"]', '["sh", "-c", "( kubectl get pod volpod -n $NS -o jsonpath=''{.spec.volumes[*].configMap.name}'' 2>/dev/null | grep -q \\"^app-cfg$\\" ) && ( kubectl get pod volpod -n $NS -o jsonpath=''{.spec.containers[0].volumeMounts[*].mountPath}'' 2>/dev/null | grep -qw /etc/app ) && ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl exec volpod -n $NS -- cat /etc/app/GREETING 2>/dev/null)\\" = \\"hello-etude\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) && ( grep -q \\"^hello-etude$\\" /tmp/mounted.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "볼륨이 app-cfg 를 가리킨다", "cmd": ["sh", "-c", "kubectl get pod volpod -n $NS -o jsonpath=''{.spec.volumes[*].configMap.name}'' 2>/dev/null | grep -q \\"^app-cfg$\\""]}, {"label": "/etc/app 에 마운트됐다", "cmd": ["sh", "-c", "kubectl get pod volpod -n $NS -o jsonpath=''{.spec.containers[0].volumeMounts[*].mountPath}'' 2>/dev/null | grep -qw /etc/app"]}, {"label": "Pod 안의 /etc/app/GREETING 이 hello-etude 이다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl exec volpod -n $NS -- cat /etc/app/GREETING 2>/dev/null)\\" = \\"hello-etude\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}, {"label": "저장한 파일에 hello-etude 가 있다", "cmd": ["sh", "-c", "grep -q \\"^hello-etude$\\" /tmp/mounted.txt"]}]', '[{"title": "ConfigMap", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}, {"title": "Secret", "url": "https://kubernetes.io/docs/concepts/configuration/secret/"}, {"title": "컨테이너 환경 변수 정의", "url": "https://kubernetes.io/docs/tasks/inject-data-application/define-environment-variable-container/"}]'),
  (236, 7, 'describe 로 CreateContainerConfigError 원인 찾기', 'Pod `broken` 이 Running 이 되지 못하고 있습니다. `get pod` 의 STATUS 를 보고, **`describe` 결과를 `/tmp/describe.txt` 에 저장**한 뒤 파일에서 무엇이 없다고 하는지 읽어 보세요.', '`kubectl get pod broken` 의 STATUS 를 먼저 보고, `kubectl describe pod broken > 파일` 로 저장해 `cat` 으로 읽어요. 맨 아래 Events 와 State 의 Reason 이 단서예요.', 'kubectl get pod broken -n $NS
kubectl describe pod broken -n $NS > /tmp/describe.txt
cat /tmp/describe.txt

# STATUS 는 CreateContainerConfigError, Events 에 ''configmap "pay-cfg" not found''
# 컨테이너가 시작되기 전에 설정(ConfigMap 참조)을 만들다 막힌 것이다. 이미지나 명령 문제가 아니다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/app.properties; kubectl delete pod envdemo volpod broken -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete deployment api -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete configmap app-cfg file-cfg pay-cfg -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete secret db-secret -n $NS --ignore-not-found >/dev/null 2>&1; cat <<EOF | kubectl apply -n $NS -f - >/dev/null 2>&1\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: broken\\nspec:\\n  containers:\\n  - name: main\\n    image: busybox:1.36\\n    command: [\\"sleep\\", \\"3600\\"]\\n    env:\\n    - name: MODE\\n      valueFrom:\\n        configMapKeyRef:\\n          name: pay-cfg\\n          key: MODE\\nEOF\\ni=0; while [ $i -lt 60 ]; do r=$(kubectl get pod broken -n $NS -o jsonpath=''{.status.containerStatuses[0].state.waiting.reason}'' 2>/dev/null); [ \\"$r\\" = CreateContainerConfigError ] && break; sleep 1; i=$((i+1)); done; true"]', '["sh", "-c", "( grep -q \\"^Name:.*broken\\" /tmp/describe.txt ) && ( grep -q \\"CreateContainerConfigError\\" /tmp/describe.txt ) && ( grep -q \\"pay-cfg\\" /tmp/describe.txt && grep -q \\"not found\\" /tmp/describe.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "describe 결과가 저장됐다", "cmd": ["sh", "-c", "grep -q \\"^Name:.*broken\\" /tmp/describe.txt"]}, {"label": "CreateContainerConfigError 가 보인다", "cmd": ["sh", "-c", "grep -q \\"CreateContainerConfigError\\" /tmp/describe.txt"]}, {"label": "없는 ConfigMap 이름 pay-cfg 가 보인다", "cmd": ["sh", "-c", "grep -q \\"pay-cfg\\" /tmp/describe.txt && grep -q \\"not found\\" /tmp/describe.txt"]}]', '[{"title": "ConfigMap", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}, {"title": "Secret", "url": "https://kubernetes.io/docs/concepts/configuration/secret/"}, {"title": "컨테이너 환경 변수 정의", "url": "https://kubernetes.io/docs/tasks/inject-data-application/define-environment-variable-container/"}]'),
  (236, 8, '없는 ConfigMap 만들어 Pod 살리기', 'Pod `broken` 은 ConfigMap `pay-cfg` 의 키 `MODE` 를 환경변수로 쓰려는데 `pay-cfg` 가 없어서 시작하지 못합니다. **Pod 는 건드리지 말고** ConfigMap `pay-cfg` 를 만들어(키 `MODE`, 값 `live`) Pod 가 Running 이 되게 하세요.', 'Pod 를 지우고 다시 만들 필요 없어요. 없던 ConfigMap 이 생기면 kubelet 이 다시 시도해서 컨테이너를 시작합니다. 잠시 기다린 뒤 `kubectl get pod broken` 으로 보세요.', 'kubectl create configmap pay-cfg --from-literal=MODE=live -n $NS
kubectl wait --for=condition=Ready pod/broken -n $NS --timeout=90s
kubectl exec broken -n $NS -- printenv MODE

# 참조하던 ConfigMap 만 채우면 Pod 는 저절로 시작된다
# 키 이름까지 맞아야 한다 (ConfigMap 은 있어도 키가 없으면 같은 오류가 난다)', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/app.properties; kubectl delete pod envdemo volpod broken -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete deployment api -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete configmap app-cfg file-cfg pay-cfg -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete secret db-secret -n $NS --ignore-not-found >/dev/null 2>&1; cat <<EOF | kubectl apply -n $NS -f - >/dev/null 2>&1\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: broken\\nspec:\\n  containers:\\n  - name: main\\n    image: busybox:1.36\\n    command: [\\"sleep\\", \\"3600\\"]\\n    env:\\n    - name: MODE\\n      valueFrom:\\n        configMapKeyRef:\\n          name: pay-cfg\\n          key: MODE\\nEOF\\ni=0; while [ $i -lt 60 ]; do r=$(kubectl get pod broken -n $NS -o jsonpath=''{.status.containerStatuses[0].state.waiting.reason}'' 2>/dev/null); [ \\"$r\\" = CreateContainerConfigError ] && break; sleep 1; i=$((i+1)); done; true"]', '["sh", "-c", "( [ \\"$(kubectl get configmap pay-cfg -n $NS -o jsonpath=''{.data.MODE}'' 2>/dev/null)\\" = \\"live\\" ] ) && ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pod broken -n $NS -o jsonpath=''{.status.containerStatuses[0].ready}'' 2>/dev/null)\\" = \\"true\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) && ( i=0; while [ $i -lt 30 ]; do if [ \\"$(kubectl exec broken -n $NS -- printenv MODE 2>/dev/null)\\" = \\"live\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "ConfigMap pay-cfg 의 MODE 가 live 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get configmap pay-cfg -n $NS -o jsonpath=''{.data.MODE}'' 2>/dev/null)\\" = \\"live\\" ]"]}, {"label": "Pod broken 이 Ready 가 됐다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pod broken -n $NS -o jsonpath=''{.status.containerStatuses[0].ready}'' 2>/dev/null)\\" = \\"true\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}, {"label": "Pod 안에서 MODE 가 live 이다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 30 ]; do if [ \\"$(kubectl exec broken -n $NS -- printenv MODE 2>/dev/null)\\" = \\"live\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}]', '[{"title": "ConfigMap", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}, {"title": "Secret", "url": "https://kubernetes.io/docs/concepts/configuration/secret/"}, {"title": "컨테이너 환경 변수 정의", "url": "https://kubernetes.io/docs/tasks/inject-data-application/define-environment-variable-container/"}]'),
  (236, 9, 'ConfigMap 을 고친 뒤 이미 떠 있는 Pod 는', '같은 ConfigMap 을 Pod A 는 **환경변수**로, Pod B 는 **볼륨(파일)** 으로 쓰고 있습니다. ConfigMap 의 값을 고치고 Pod 는 그대로 둔 채 1~2분이 지나면 어떻게 될까요?', '환경변수는 컨테이너가 시작될 때 한 번 정해지고, 볼륨은 kubelet 이 파일을 계속 동기화해요.', NULL, NULL, '[]', 'choice', '["Pod A 의 환경변수와 Pod B 의 파일 모두 즉시 새 값으로 바뀐다", "Pod A 의 환경변수만 새 값으로 바뀌고 Pod B 의 파일은 그대로다", "Pod B 의 파일은 새 값으로 바뀌지만, Pod A 의 환경변수는 Pod 를 다시 만들기 전까지 옛 값 그대로다", "Pod A 와 Pod B 모두 Pod 를 다시 만들기 전까지 옛 값 그대로다"]', 2, '환경변수는 컨테이너 프로세스가 시작될 때 값이 정해져 실행 중에는 바뀌지 않으므로, 새 값을 쓰려면 Pod 를 다시 만들어야 합니다. 볼륨으로 마운트한 ConfigMap 은 kubelet 이 주기적으로 동기화해서 잠시(대개 1분 안팎) 뒤 파일 내용이 새 값으로 바뀝니다. 단, `subPath` 로 마운트한 파일은 갱신되지 않고, 앱이 파일을 다시 읽어야 새 값을 씁니다.', NULL, NULL, NULL, NULL),
  (236, 10, 'kubectl set env --from 으로 Deployment 에 연결', 'Deployment `api` 와 ConfigMap `app-cfg`(`GREETING`, `LEVEL`) 가 있습니다. YAML 을 고치지 말고 **명령 한 줄로** `app-cfg` 의 **모든 키**를 `api` 의 환경변수로 연결하세요. 새 Pod 가 뜨면 `kubectl exec` 으로 `GREETING` 값을 확인합니다.', '`kubectl set env deployment/이름 --from=configmap/이름` 형식이에요. 환경변수를 바꾸면 Deployment 가 Pod 를 새로 띄웁니다.', 'kubectl set env deployment/api --from=configmap/app-cfg -n $NS
kubectl rollout status deployment/api -n $NS
kubectl exec deploy/api -n $NS -- printenv GREETING

# 키 하나씩이 아니라 ConfigMap 전체가 envFrom 으로 연결된다
# Pod 템플릿이 바뀌므로 롤링 업데이트로 새 Pod 가 뜬다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/app.properties; kubectl delete pod envdemo volpod broken -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete deployment api -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete configmap app-cfg file-cfg pay-cfg -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete secret db-secret -n $NS --ignore-not-found >/dev/null 2>&1; kubectl create configmap app-cfg --from-literal=GREETING=hello-etude --from-literal=LEVEL=info -n $NS >/dev/null 2>&1; cat <<EOF | kubectl apply -n $NS -f - >/dev/null 2>&1\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: api\\nspec:\\n  replicas: 1\\n  selector:\\n    matchLabels:\\n      app: api\\n  template:\\n    metadata:\\n      labels:\\n        app: api\\n    spec:\\n      containers:\\n      - name: main\\n        image: nginx:1.25\\nEOF\\nkubectl rollout status deployment/api -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get deployment api -n $NS -o jsonpath=''{.spec.template.spec.containers[0].env[0].valueFrom.configMapKeyRef.name}'' 2>/dev/null)\\" = \\"app-cfg\\" ] ) && ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl exec deploy/api -n $NS -- printenv GREETING 2>/dev/null)\\" = \\"hello-etude\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) && ( i=0; while [ $i -lt 30 ]; do if [ \\"$(kubectl exec deploy/api -n $NS -- printenv LEVEL 2>/dev/null)\\" = \\"info\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "환경변수가 app-cfg 를 가리킨다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment api -n $NS -o jsonpath=''{.spec.template.spec.containers[0].env[0].valueFrom.configMapKeyRef.name}'' 2>/dev/null)\\" = \\"app-cfg\\" ]"]}, {"label": "새 Pod 안에서 GREETING 이 hello-etude 이다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl exec deploy/api -n $NS -- printenv GREETING 2>/dev/null)\\" = \\"hello-etude\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}, {"label": "새 Pod 안에서 LEVEL 이 info 이다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 30 ]; do if [ \\"$(kubectl exec deploy/api -n $NS -- printenv LEVEL 2>/dev/null)\\" = \\"info\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}]', '[{"title": "ConfigMap", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}, {"title": "Secret", "url": "https://kubernetes.io/docs/concepts/configuration/secret/"}, {"title": "컨테이너 환경 변수 정의", "url": "https://kubernetes.io/docs/tasks/inject-data-application/define-environment-variable-container/"}]'),
  (236, 11, 'ConfigMap 을 고치고 rollout restart 로 반영', 'Deployment `api` 는 ConfigMap `app-cfg` 를 `envFrom` 으로 쓰고 있고 지금 `LEVEL` 은 `info` 입니다. ConfigMap 의 **`LEVEL` 을 `debug` 로 바꾸고**, 실행 중인 `api` Pod 안에서도 `debug` 로 보이게 하세요. Deployment 를 지우거나 환경변수를 YAML 에 직접 적지 마세요.', 'ConfigMap 은 `kubectl patch configmap 이름 -p ...` 로 한 키만 바꿀 수 있어요. 환경변수는 Pod 를 다시 만들어야 바뀌니, Deployment 의 Pod 를 새로 띄우는 `kubectl rollout restart` 를 써 보세요.', 'kubectl patch configmap app-cfg -n $NS -p ''{"data":{"LEVEL":"debug"}}''
kubectl rollout restart deployment/api -n $NS
kubectl rollout status deployment/api -n $NS
kubectl exec deploy/api -n $NS -- printenv LEVEL

# ConfigMap 만 고치면 환경변수는 그대로다. restart 로 새 Pod 를 띄워야 새 값을 읽는다
# Deployment 는 새 Pod 를 먼저 띄운 뒤 옛 Pod 를 내리므로 중단 없이 바뀐다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/app.properties; kubectl delete pod envdemo volpod broken -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete deployment api -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete configmap app-cfg file-cfg pay-cfg -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete secret db-secret -n $NS --ignore-not-found >/dev/null 2>&1; kubectl create configmap app-cfg --from-literal=GREETING=hello-etude --from-literal=LEVEL=info -n $NS >/dev/null 2>&1; cat <<EOF | kubectl apply -n $NS -f - >/dev/null 2>&1\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: api\\nspec:\\n  replicas: 1\\n  selector:\\n    matchLabels:\\n      app: api\\n  template:\\n    metadata:\\n      labels:\\n        app: api\\n    spec:\\n      containers:\\n      - name: main\\n        image: nginx:1.25\\n        envFrom:\\n        - configMapRef:\\n            name: app-cfg\\nEOF\\nkubectl rollout status deployment/api -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get configmap app-cfg -n $NS -o jsonpath=''{.data.LEVEL}'' 2>/dev/null)\\" = \\"debug\\" ] ) && ( [ \\"$(kubectl get deployment api -n $NS -o jsonpath=''{.spec.template.spec.containers[0].envFrom[0].configMapRef.name}'' 2>/dev/null)\\" = \\"app-cfg\\" ] ) && ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl exec deploy/api -n $NS -- printenv LEVEL 2>/dev/null)\\" = \\"debug\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "ConfigMap 의 LEVEL 이 debug 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get configmap app-cfg -n $NS -o jsonpath=''{.data.LEVEL}'' 2>/dev/null)\\" = \\"debug\\" ]"]}, {"label": "Deployment 는 여전히 app-cfg 를 envFrom 으로 쓴다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment api -n $NS -o jsonpath=''{.spec.template.spec.containers[0].envFrom[0].configMapRef.name}'' 2>/dev/null)\\" = \\"app-cfg\\" ]"]}, {"label": "Pod 안에서 LEVEL 이 debug 이다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl exec deploy/api -n $NS -- printenv LEVEL 2>/dev/null)\\" = \\"debug\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}]', '[{"title": "ConfigMap", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}, {"title": "Secret", "url": "https://kubernetes.io/docs/concepts/configuration/secret/"}, {"title": "컨테이너 환경 변수 정의", "url": "https://kubernetes.io/docs/tasks/inject-data-application/define-environment-variable-container/"}]'),
  (236, 12, '설정 값을 바꿔서 앱에 반영하는 순서', 'Deployment 가 ConfigMap 의 값을 환경변수로 쓰도록 연결하고, 나중에 값을 바꿔 반영하는 순서입니다. 순서에 맞게 놓아 보세요.', '만들고 연결해서 처음 값을 확인한 뒤, 값을 바꾸고 Pod 를 새로 띄워 바뀐 값을 다시 확인해요.', NULL, NULL, '[]', 'order', '["`kubectl patch configmap app-cfg ...` 로 LEVEL 값을 debug 로 바꾼다", "`kubectl create configmap app-cfg --from-literal=LEVEL=info` 로 ConfigMap 을 만든다", "`kubectl exec deploy/api -- printenv LEVEL` 을 다시 실행해 debug 로 바뀐 것을 확인한다", "`kubectl set env deployment/api --from=configmap/app-cfg` 로 Deployment 에 연결한다", "`kubectl rollout restart deployment/api` 로 Pod 를 새로 띄운다", "`kubectl exec deploy/api -- printenv LEVEL` 로 처음 값 info 를 확인한다"]', NULL, '먼저 ConfigMap 을 만들고 `set env --from` 으로 Deployment 에 연결하면 새 Pod 가 info 를 읽습니다. 처음 값을 확인한 뒤 patch 로 ConfigMap 을 고쳐도 환경변수는 실행 중인 Pod 에 반영되지 않아요. `rollout restart` 로 Pod 를 새로 띄운 뒤 같은 명령으로 다시 확인하면 debug 가 보입니다.', '[1, 3, 5, 0, 4, 2]', NULL, NULL, NULL);
